import assert from "node:assert/strict";
import { spawnSync } from "node:child_process";
import { createHash } from "node:crypto";
import { readFileSync } from "node:fs";
import { resolve } from "node:path";
import test from "node:test";
import {
  buildTicketAuthorityIndex,
  parseTicketOwnershipAndRed,
  resolveExecutionState
} from "../../scripts/resolve-execution-state.mjs";
import {
  SUPPORTED_NODE_RANGE,
  isSupportedNodeVersion
} from "../../scripts/schema-conformance.mjs";

const root = resolve(new URL("../..", import.meta.url).pathname);
const read = (path) => readFileSync(resolve(root, path), "utf8");
const digest = (text) => createHash("sha256").update(text, "utf8").digest("hex");

test("D0-010 is a resolver-evaluable Node 22.18 runtime contract", () => {
  assert.equal(SUPPORTED_NODE_RANGE, ">=22.18 <25");
  assert.equal(isSupportedNodeVersion("22.18.0"), true);
  assert.equal(isSupportedNodeVersion("20.19.0"), false);

  const catalog = JSON.parse(read("docs/issues.json"));
  const records = catalog.tickets.filter((record) => record.id === "D0-010");
  assert.equal(records.length, 1, "D0-010 must have one canonical catalog record");

  const record = records[0];
  assert.equal(record.issue, 167);
  assert.equal(record.epic, "D0");
  assert.equal(record.milestone, "S0 · Name & Contracts");
  assert.deepEqual(record.dependencies, ["D0-002"]);

  const authorityIndex = buildTicketAuthorityIndex(read("docs/TRACEABILITY.md"));
  assert.equal(authorityIndex.ok, true, authorityIndex.reason);
  const authority = authorityIndex.index["D0-010"];
  assert.ok(authority, "the authority graph must expose D0-010");
  assert.equal(authority.prd_path, "docs/prd/PRD-D0-name-migration-and-repository-skeleton.md");
  assert.deepEqual(authority.adr_ids, ["ADR-0001", "ADR-0003", "ADR-0012"]);

  const ticketText = read(record.ticket_path);
  const contract = parseTicketOwnershipAndRed(ticketText, { ticketId: "D0-010" });
  assert.equal(contract.ok, true, contract.reason);
  assert.ok(contract.owned_paths.length > 0, "the resolver needs declared owned paths");
  assert.ok(contract.owned_symbols.length > 0, "the resolver needs declared owned symbols");
  assert.ok(contract.red_command, "the resolver needs a RED command");

  const facts = JSON.parse(read("fixtures/operational-state/current-baseline/facts.json"));
  const ticketDigest = digest(ticketText);
  const prdDigest = digest(read(authority.prd_path));
  facts.liveDigests[record.ticket_path] = ticketDigest;
  facts.liveDigests[authority.prd_path] = prdDigest;
  facts.tickets["D0-010"] = {
    kind: "executable",
    dependencies: record.dependencies,
    owned_paths: contract.owned_paths,
    owned_symbols: contract.owned_symbols,
    red_command: contract.red_command,
    prd_path: authority.prd_path,
    adr_paths: {},
    digests: {
      ticket: ticketDigest,
      prd: prdDigest,
      prd_path: authority.prd_path,
      adrs: {},
      adr_paths: {}
    }
  };

  const state = resolveExecutionState({
    mode: "offline",
    facts,
    now: "2026-08-23T00:00:00.000Z",
    runtimeIdentity: {
      repository: facts.repository,
      branch: facts.defaultBranch,
      head: facts.currentHead
    }
  });
  const evaluation = state.tickets["D0-010"];
  assert.ok(evaluation, "the resolver must classify D0-010");
  assert.doesNotInclude(
    evaluation.blockers.map(({ code }) => code),
    "TICKET_CONTRACT_INCOMPLETE",
    "a complete contract must not be rejected as incomplete"
  );
  assert.doesNotInclude(
    evaluation.blockers.map(({ code }) => code),
    "RED_CONTRACT_INVALID",
    "a complete contract must provide an executable RED command"
  );

  const rendered = spawnSync(process.execPath, ["scripts/render-execution-views.mjs", "--check"], {
    cwd: root,
    encoding: "utf8"
  });
  assert.equal(rendered.status, 0, rendered.stderr);
  assert.match(rendered.stdout, /EXECUTION_VIEWS_CHECK surfaces=2 drift=0 conflicts=0/);
});
